private double normalizeLongitude(double lon) {
    lon = lon % 360;
    if (lon > 180) {
        lon -= 360;
    } else if (lon < -180) {
        lon += 360;
    }
    return Math.max(-180.0, Math.min(180.0, lon));
}

private double normalizeLatitude(double lat) {
    return Math.max(-90.0, Math.min(90.0, lat));
}
