                while (buf.readerIndex() < endIndex) {
                    int sensorIndex = buf.readUnsignedByte();
                    buf.skipBytes(6); // mac
                    position.set(Position.PREFIX_TEMP + sensorIndex, decodeCustomDouble(buf));
                    position.set("humidity" + sensorIndex, decodeCustomDouble(buf));
